#include <iostream>
using namespace std;
int main() {
    int i = 10;          // счётчик (начало)
    while (i > 0) {      // пока i больше 0
        cout << i << endl;
        i--;             // уменьшаем счётчик (шаг)
    }
    cout << "Поехали!" << endl;
    return 0;
}

int n;
cin >> n;
int count = 0;      // количество промежуточных делителей
int i = n - 1;      // исключаем само число n
while (i > 1)       // пока не переберём все числа между 1 и n
{
    if (n % i == 0) // нашли промежуточный делитель
        count++;
    i--;            // берём следующее i
}
if (count == 0)
    cout << n << " - простое число";
else
    cout << n << " - не простое число";

int N, factorial = 1;
cout << "Введите число N: ";
cin >> N;
int i = 1;
while (i <= N) {
    factorial *= i;
    i++;
}
cout << "Факториал числа " << N << " равен " << factorial << endl;

```cpp
int n = 123;
int sum = 0;
while (n > 0) {
    sum += n % 10;  // берём последнюю цифру
    n = n / 10;     // отбрасываем её
}
cout << sum;
```

| n | n % 10 | sum | n / 10 |
|---|---|---|---|
| 123 | 3 | 3 | 12 |
| 12 | 2 | 5 | 1 |
| 1 | 1 | 6 | 0 |

n = 0 — цикл завершается, сумма цифр 6.

